#include "stdafx.h"#include "SOEtransport.h"#include <macros/AutoCloser.h>#include <macros/StrHelps.h>#include <rsuPaths.h>#include <rsuErr.h>#include <rsuMemoryManager.h>extern KRsuMemoryManager g_SOEmemory;KSOEtransport::KSOEtransport(  char * _ObjName ):	IBaseModel ( _ObjName ){  ObjName = _ObjName;  TypeObj = RSU_Obj;}KSOEtransport::~KSOEtransport(void){}int KSOEtransport::Init( int ){  return 0;}int KSOEtransport::Step1(){  InitLink();  return 0;}template<int X, int Y>bool FindColumn( LPCSTR pszName, int &index, const char (&header)[X][Y] ){  for( int i=0; i<X; ++i )  {    if( !_strcmpi(header[i], pszName) )    {      index = i;      return true;    }  }  return false;}#define FINDCOLUMN( x ) if( !FindColumn(#x, m_Header.indexes.x, row) ) return;void KSOEtransport::InitLink(){  OutputDebugString( "SOEtransport::InitLink...\n" );  DWORD s = GetTickCount();  char* Q = setlocale( LC_ALL, "Russian" );  char Path[_MAX_PATH];  sprintf_s( Path, "%sData\\Acy\\SOE.csv", rsuGetProjectPath() );  char str[512];  char row[20][128] = { 0 };  {    KAutoCloser<FILE*> F( fopen( Path, "rt"), fclose );    if( !F )      return;    fgets( str, _countof(str)-1, F );    LPCSTR pszHeader = str;    if( '#'==*pszHeader )      ++pszHeader;    int C = SplitString2( pszHeader, row, ';', false );    FINDCOLUMN( masterRSU )    FINDCOLUMN( masterPNT )    FINDCOLUMN( masterIOTYPE )    FINDCOLUMN( slaveRSU )    FINDCOLUMN( slavePNT )    while( fgets( str, _countof(str)-1, F ) )    {      C = SplitString2( str, row, ';', false );      bool bAllColumns = true;      for( int i=0; i<_countof(m_Header.array); ++ i)      {        LPCSTR pszRec = row[ m_Header.array[i] ];        if( 0==*pszRec )        {          bAllColumns = false;          break;        }      }      if( bAllColumns )        ++m_nRecords;    }  }  if( !m_nRecords )    return;  m_pExchange = new( g_SOEmemory.AllocMemory( m_nRecords*sizeof(SExchange) ) ) SExchange[m_nRecords] ;  if( !m_pExchange )  {    m_nRecords = 0;    return;  }  KAutoCloser<FILE*> F( fopen( Path, "rt"), fclose );  if( !F )    return;  sprintf_s( Path, "%sData\\Acy\\ошибки_в_SOE.csv", GetBasePath());  KAutoCloser<FILE*> errs;  int nLine = 1;  fgets( str, _countof(str)-1, F );  int N = 0;  while( fgets( str, _countof(str)-1, F ) )  {    ++nLine;    int C = SplitString2( str, row, ';', false );    bool bAllColumns = true;    for( int i=0; i<_countof(m_Header.array); ++ i)    {      LPCSTR pszRec = row[ m_Header.array[i] ];      if( 0==*pszRec )      {        bAllColumns = false;        break;      }    }    if( !bAllColumns )      continue;    SExchange &exchange = m_pExchange[N];    LPSTR pszIOTYPE = row[m_Header.indexes.masterIOTYPE];    if( 'D'==pszIOTYPE[0] )      exchange.bDigital = true;    else if( 'A'==pszIOTYPE[0] )      exchange.bDigital = false;    else    {      ASSD(0);      continue;    }    LPSTR pPnt = row[m_Header.indexes.masterPNT];    LPSTR pSepBit = strchr( pPnt, '.' );    int masterBitIndex = -1;    if( pSepBit )    {      *pSepBit = 0;      ++pSepBit;      masterBitIndex = atoi( pSepBit );    }    int r = exchange.rsuMaster.LinkTo( row[m_Header.indexes.masterPNT], pszIOTYPE, row[m_Header.indexes.masterRSU] );    if( r )    {      if( !errs )        errs.Assign( fopen( Path, "wt"), fclose );      if( errs )        fprintf( errs, "строка %d, не соединиться с master %s точкой %s (%s)\n", nLine, pszIOTYPE, row[m_Header.indexes.masterPNT], row[m_Header.indexes.masterRSU] );      continue;    }    if( -1 != masterBitIndex )    {      exchange.rsuMaster.SetBitOffset( masterBitIndex );    }    if( 'I'==pszIOTYPE[1] )    {      pszIOTYPE[1] = 'O';      exchange.bInput4Master = true;    }    else if( 'O'==pszIOTYPE[1] )    {      pszIOTYPE[1] = 'I';      exchange.bInput4Master = false;    }    else    {      ASSD(0);      continue;    }    pPnt = row[m_Header.indexes.slavePNT];    pSepBit = strchr( pPnt, '.' );    int slaveBitIndex = -1;    if( pSepBit )    {      *pSepBit = 0;      ++pSepBit;      slaveBitIndex = atoi( pSepBit );    }    r = exchange.rsuSlave.LinkTo( row[m_Header.indexes.slavePNT], pszIOTYPE, row[m_Header.indexes.slaveRSU] );    if( r )    {      if( !errs )        errs.Assign( fopen( Path, "wt"), fclose );      if( errs )        fprintf( errs, "строка %d, не соединиться со slave %s точкой %s (%s)\n", nLine, pszIOTYPE, row[m_Header.indexes.slavePNT], row[m_Header.indexes.slaveRSU] );      continue;    }    if( -1 != slaveBitIndex )    {      exchange.rsuSlave.SetBitOffset( slaveBitIndex );    }    ++N;    if( N==m_nRecords )      break;  }  DWORD c = GetTickCount();  DWORD d = c - s;  char szDebug[128];  sprintf_s( szDebug, "KSOEtransport: время связывания %d из заявленных %d точек %d ms\n", N, m_nRecords, d );  OutputDebugString( szDebug );  m_nRecords = N;  errs.Reset();}int KSOEtransport::StepT(double dt){  for( int i=0; i<m_nRecords; ++i )  {    SExchange &exchange = m_pExchange[i];    if( exchange.bInput4Master )      Exchange( exchange.rsuMaster, exchange.rsuSlave, exchange.bDigital );    else      Exchange( exchange.rsuSlave, exchange.rsuMaster, exchange.bDigital );  }  return 0;}void KSOEtransport::Exchange( KRsuX &dest, KRsuX &src, bool bDig ){  if( bDig )  {    int val = src;    dest = val;  }  else  {    double val = src;    dest = val;  }}